import { injectable } from 'inversify';
import { IProductStatusRepository } from '@src/domain/interfaces/loan_product/product_status';
import { ProductStatusResponse } from '@src/domain/entities/loan_product/product_status';
import { HttpService } from '@core/service';
import { BASE_URL_LOAN_API } from '@src/config';
import { ProductStatusPayload } from '@src/application/loan_product/queries/get_product_status/get_product_status_query';
import { Query } from '@src/domain/models/query';
import uuid from 'react-native-uuid';
import { commonService } from '@src/infrastructure/network/networkService';

@injectable()
export class ProductStatusRepository extends HttpService implements IProductStatusRepository {
    constructor() {
        super({ baseURL: BASE_URL_LOAN_API });
    }
    async getProductStatus<TParameter>(query: Query<TParameter>): Promise<ProductStatusResponse> {
        const request = query as unknown as ProductStatusPayload;
        const url = '/productStatus';
        const dataReq = {
            requestId: uuid.v4(),
            channel: String(request.channel),
            ipRequest: String(request.ipRequest),
            language: String(request.language),
            deviceInfo: {
                deviceId: String(request.deviceInfo.deviceId),
                deviceName: String(request.deviceInfo.deviceName),
                os: String(request.deviceInfo.os),
                osVersion: String(request.deviceInfo.osVersion),
            },
            data: {
                clientNo: String(request.data.clientNo),
                productCode: String(request.data.productCode),
                loanAmt: String(request.data.loanAmt),
            },
        };

        const { data } = await this.post(url, dataReq, {
            headers: commonService.getHeader({ 'X-CHANNEL': 'mfe-loan' }),
        });
        // console.log('\x1b[36m response product status', data);
        return data as ProductStatusResponse;
    }
}
