import { HttpService } from '@core/service';
import { DepositAccountPayload } from '@src/application/loan_collateral/getListDepositAccounts/depositAccount_query';
import { BASE_URL_LOAN_API } from '@src/config';
import { DepositAccountResponse } from '@src/domain/entities/loan_collateral/depositAccount';
import type { IDepositAccountRepository } from '@src/domain/interfaces/loan_collateral/depositAccount';
import { Query } from '@src/domain/models/query';
import { commonService } from '@src/infrastructure/network/networkService';
import uuid from 'react-native-uuid';

export class DepositAccountRepository extends HttpService implements IDepositAccountRepository {
    constructor() {
        super({ baseURL: BASE_URL_LOAN_API });
    }
    async getListDepositAccounts<TParameter>(query: Query<TParameter>): Promise<DepositAccountResponse> {
        const request = query.query as unknown as DepositAccountPayload;
        const url = '/getListDepositAccounts';
        const params = {
            requestId: uuid.v4(),
            channel: String(request.channel),
            ipRequest: String(request.ipRequest),
            language: String(request.language),
            deviceInfo: {
                deviceId: String(request.deviceInfo.deviceId),
                deviceName: String(request.deviceInfo.deviceName),
                os: String(request.deviceInfo.os),
                osVersion: String(request.deviceInfo.osVersion),
            },
            data: {
                clientNo: String(request.data.clientNo),
            },
        };

        const { data } = await this.post(url, params, {
            headers: commonService.getHeader({ 'X-CHANNEL': 'mfe-loan-collateral' }),
        });
        return data as DepositAccountResponse;
    }
}
